package xyz.shuncongci.leica

import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.junit.runners.Parameterized
import java.io.*
import java.nio.file.Files
import xyz.shuncongci.leica.LegendaryMath.Frame

/** Dense signed HDR, non-monotone CoC, large reflected supports and exact-zero cases.
 * Every expected Float32 byte was generated by the verified frozen 68 jar, not this code. */
@RunWith(Parameterized::class)
class HdrScatterExactTest(private val case:Int,private val band:Int) {
    companion object { @JvmStatic @Parameterized.Parameters(name="case{0}-band{1}") fun cases()=(0..11).flatMap{c->listOf(1,17,128).map{b->arrayOf(c,b)}} }
    private fun fixture(name:String):Frame {
        val path="/exact-radiance68/case$case/$name.f32"
        DataInputStream(javaClass.getResourceAsStream(path)?:error(path)).use{f->
            require(f.readInt()==0x4c435031);val w=f.readInt();val h=f.readInt();val c=f.readInt()
            return Frame(w,h,c,FloatArray(w*h*c){f.readFloat()}).also{check(f.read()==-1)}
        }
    }
    private fun assertCase(solo:Boolean){
        val root=Files.createTempDirectory("hdr-scatter-exact-").toFile();val co=fixture("coc");val before=co.data.copyOf();val files=arrayListOf<BokehFloatFile>()
        val groups=if(solo)listOf(1)else listOf(0,1);val progress=arrayListOf<Int>()
        try {
            val input=groups.map{g->val src=fixture("source$g");BokehFloatFile.create(File(root,"in$g"),co.w,co.h,3).also{files.add(it);it.put(src,it.whole,Cancel())}}
            val output=groups.map{g->BokehFloatFile.create(File(root,"color$g"),co.w,co.h,3).also(files::add)}
            val fronts=if(solo)null else groups.map{g->BokehFloatFile.create(File(root,"front$g"),co.w,co.h,3).also(files::add)}
            val stats=RadianceTransport.Stats()
            StreamingLightScatter.Pupils(co.w,co.h,2.8f,root).use{p->RadianceTransport.run(input,co,2.8f,Cancel(),output,fronts,BooleanArray(groups.size){groups[it]==1},p,band,{n,total->assertEquals(co.h,total);progress.add(n)},stats)}
            for((i,g) in groups.withIndex())for((name,actual) in listOfNotNull("color" to output[i],fronts?.let{"front" to it[i]})){
                val want=fixture("$name$g").data;val got=actual.read(actual.whole,Cancel()).data
                assertEquals(want.size,got.size);for(at in want.indices)assertEquals("$name$g@$at",want[at].toRawBits(),got[at].toRawBits())
            }
            val expected=(0 until co.h step band).map{minOf(co.h,it+band)}
            assertEquals(expected,progress);assertEquals(co.h,stats.receiverRows);assertTrue(stats.maxSourceRows<=minOf(co.h,band+2*(kotlin.math.ceil(co.data.maxOf{kotlin.math.abs(it)}).toInt()+1)))
            assertArrayEquals(before,co.data,0f)
            for((i,g) in groups.withIndex())assertArrayEquals(fixture("source$g").data,input[i].read(input[i].whole,Cancel()).data,0f)
        } finally {files.forEach{it.close()};root.walkBottomUp().forEach{it.delete()}}
    }
    @Test fun dualOutputAndForegroundMatch68RawBits()=assertCase(false)
    @Test fun singleSignedWithoutForegroundMatches68RawBits()=assertCase(true)
}
